<div class="form-grid"><label>Nombre completo *<input name="name" required value="{{ old('name',optional($user)->name) }}"></label><label>Correo electrónico *<input type="email" name="email" required value="{{ old('email',optional($user)->email) }}"></label><label>Contraseña {{ $user?'':'*' }}<input type="password" name="password" {{ $user?'':'required' }} placeholder="{{ $user?'Dejar vacío para mantener':'Mínimo 8 caracteres' }}"></label><label>Sucursal *<input name="branch" required value="{{ old('branch',optional($user)->branch ?? 'Almacén principal') }}"></label><label>Perfil *<select name="profile">@foreach(['Administrador','Aprobador','Almacenero','Evaluador','Consulta'] as $profile)<option {{ optional($user)->profile===$profile?'selected':'' }}>{{ $profile }}</option>@endforeach</select></label>
<fieldset class="permission-tree"><legend>Accesos por módulos y submódulos *</legend>@foreach($permissionModules as $moduleKey=>$module)<section class="permission-module"><label class="permission-module-title"><input type="checkbox" class="permission-module-toggle"> <span><strong>{{ $module['label'] }}</strong><small>Seleccionar todos los submódulos</small></span></label><div>@foreach($module['children'] as $key=>$label)<label class="check"><input type="checkbox" name="permissions[]" value="{{ $key }}" {{ ($user && $user->canAccess($key))?'checked':'' }}> {{ $label }}</label>@endforeach</div></section>@endforeach</fieldset>
<label class="check"><input type="checkbox" name="is_active" value="1" {{ optional($user)->is_active!==false?'checked':'' }}> Usuario activo</label></div>
@push('scripts')<script>document.querySelectorAll('.permission-module').forEach(module=>{const toggle=module.querySelector('.permission-module-toggle'),children=[...module.querySelectorAll('input[name="permissions[]"]')];const sync=()=>{toggle.checked=children.length>0&&children.every(input=>input.checked);toggle.indeterminate=children.some(input=>input.checked)&&!toggle.checked;};toggle.addEventListener('change',()=>{children.forEach(input=>input.checked=toggle.checked);sync();});children.forEach(input=>input.addEventListener('change',sync));sync();});</script>@endpush
